entries[336734] = { ["name"] = "Flammender Untergang des Himmelsbrechers", ["text"] = "Runenschnitzmacht\nWenn der regelmäßige Schaden von 'Flammenschock' einen kritischen Treffer erzielt, wird die Abklingzeit von [ Sturmelementar : 'Sturmelementar' / 'Feuerelementar'] um [ Sturmelementar : 1.0 / 1.0] Sek. verringert. Außerdem ist die kritische Trefferchance von 'Flammenschock' um 50% erhöht.\nRunenschnitzen: Brust, Finger\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Schamane (Elementar)" }
entries[336735] = { ["name"] = "Ketten der Verheerung", ["text"] = "Runenschnitzmacht\nSofort\nElementar\n'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber und lässt ihn 50% mehr Schaden verursachen. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber und lässt ihn kein Mana verbrauchen.\n\nVerstärkung, Wiederherstellung\n'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Schamane" }
entries[336736] = { ["name"] = "Ketten der Verheerung", ["text"] = "Sofort\nElementar\n'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber und lässt ihn 50% mehr Schaden verursachen. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber und lässt ihn kein Mana verbrauchen.\n\nVerstärkung, Wiederherstellung\n'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber." }
