entries[336738] = { ["name"] = "Tief verwurzelte Elemente", ["text"] = "Runenschnitzmacht\nElementar\nDer Einsatz von 'Lavaeruption' hat eine Chance von 7%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\n\nWiederherstellung\nDer Einsatz von 'Springflut' hat eine Chance von 7%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\n\nVerstärkung\nDer Einsatz von 'Sturmschlag' hat eine Chance von 8%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\nRunenschnitzen: Kopf, Schulter, Handgelenk\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Schamane" }
entries[336739] = { ["name"] = "Tiefenbebenstein", ["text"] = "Runenschnitzmacht\nEuer Erdelementar ist dauerhaft von 'Erdbeben' umgeben.\nRunenschnitzen: Taille, Füße, Finger\nQuelle: Dungeonbeute: Echelon\nBenötigt: Schamane" }
entries[336740] = { ["name"] = "Erdbeben", ["text"] = "40 Meter Reichweite\nWirken in 3 sek.\nLässt die Erde innerhalb von 8 Metern um den Zielort erzittern und aufbrechen. Gegner erleiden im Verlauf von 6 Sek. [Zaubermacht * 0.5 * 6 * (1 + Vielseitigkeit) * 0.9 * 1 * 1 * 1 * 1 ] körperlichen Schaden und werden mit einer Chance von 5% zu Boden gestoßen. Mehrere Einsätze von 'Erdbeben' können sich überlappen.\n\nDieser Zauber wird gegen einen ausgewählten Zielort eingesetzt." }
