entries[337038] = { ["name"] = "Klaue von Endereth", ["text"] = "Runenschnitzmacht\n'Blutsauger' wird jetzt 100% schneller kanalisiert und stellt Gesundheit 100% schneller wieder her.\nRunenschnitzen: Taille, Füße\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Hexenmeister" }
