entries[337065] = { ["name"] = "Säulen des Dunklen Portals", ["text"] = "Runenschnitzmacht\nMacht 'Dämonisches Tor' zu einem Spontanzauber und lässt Euren ersten Einsatz des Tors keine Abklingzeit auslösen.\n\nZusätzlich werden Gegner, durch die Ihr reist, von Netherenergie gepeitscht und zurückgestoßen.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Hexenmeister\nModifies Cast Time -100%:\nDämonisches Tor" }
entries[337068] = { ["name"] = "Verlorener Verstand", ["text"] = "60 Meter Reichweite\nWirken in 2.5 sek.\nDisorients the target for 5 Sek..\nInflicts Shadow damage to an enemy every 1 sec for 5 Sek.." }
entries[337069] = { ["name"] = "Unheilige Nova", ["text"] = "Pakt-Fähigkeit\nSofort\nEine Explosion dunkler Energie infiziert Gegner innerhalb von 15 Metern mit 'Unheilige Transfusion' und heilt Verbündete um (150% der Zaubermacht) Gesundheit.\n\nUnheilige Transfusion\nVerursacht im Verlauf von 15 Sek. bis zu (280% der Zaubermacht) Schattenschaden, abhängig von der Anzahl Ziele. Verbündete, die diesem Ziel Schaden zufügen, werden um [(4% der Zaubermacht) * 1 ] Gesundheit geheilt." }
