entries[337328] = { ["name"] = "Bestrahlter Schleim", ["text"] = "Sofort\nReagenzien:\nLeicht bestrahlte Schleimprobe\nNach Erhalt: Ein bestrahlter Schleim bedeckt Euch und fügt Angreifern 76 Naturschaden zu, wenn Ihr getroffen werdet. Hält 1 Stunde lang an, solange Ihr Euch in den Schattenlanden im Freien befindet." }
entries[337329] = { ["name"] = "Hyperreaktiver Schleim", ["text"] = "Sofort\nCa. 2 Procs pro Minute\nReagenzien:\nHyperreaktive Schleimprobe\nNach Erhalt: Ein hyperreaktiver Schleim bindet sich an Euch. Wenn Ihr im Kampf getroffen werdet, besteht die Chance, dass sich der Schleim auf Euren Angreifer stürzt und ihm im Verlauf von 12 Sek. 14543 Schaden zufügt. Der Schleim bleibt 1 Stunde lang bei Euch, solange Ihr Euch in den Schattenlanden im Freien befindet.\n(15s Abklingzeit)" }
