entries[337340] = { ["name"] = "Kiefers Himmelsgriff", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht die Reichweite von 'Tigerklaue' auf 10 Meter und beim Einsatz springt Ihr sofort zum Ziel.\n\n'Tigerklaue' belegt das Ziel zusätzlich mit einem Effekt, der Eure kritische Trefferchance gegen das Ziel für 6 Sek. um 50% erhöht. Dieser Effekt kann pro Ziel nur einmal alle 1 Min. auftreten." }
entries[337341] = { ["name"] = "Himmelsgrifferschöpfung", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht die Reichweite von 'Tigerklaue' auf 10 Meter und beim Einsatz springt Ihr sofort zum Ziel.\n\n'Tigerklaue' belegt das Ziel zusätzlich mit einem Effekt, der Eure kritische Trefferchance gegen das Ziel für 6 Sek. um 50% erhöht. Dieser Effekt kann pro Ziel nur einmal alle 1 Min. auftreten." }
