entries[337343] = { ["name"] = "Umwölkter Fokus", ["text"] = "Runenschnitzmacht\nHeilungen mit 'Einhüllender Nebel' oder 'Beleben', während Ihr 'Beruhigender Nebel' kanalisiert, erhöhen die verursachte Heilung der beiden Fähigkeiten um 20% und verringern ihre Manakosten um 20%. Bis zu 3-mal stapelbar.\n\nWenn das Kanalisieren von 'Beruhigender Nebel' endet, wird dieser Effekt aufgehoben.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Mönch (Nebelwirker)" }
