entries[337347] = { ["name"] = "Schockwelle", ["text"] = "Wirken in 3 sek. 3 sek. Abklingzeit\nStößt eine Schockwelle aus, die körperlichen Schaden verursacht und alle Gegner in einem kegelförmigen Bereich vor dem Zaubernden für 3 Sek. betäubt." }
